#!/bin/bash
set -euo pipefail

TOKENS_FILE="tokens.json"

if [[ ! -f "$TOKENS_FILE" ]]; then
  echo "Error: $TOKENS_FILE not found"
  exit 1
fi

# Extract background color
BG=$(jq -r '.background' "$TOKENS_FILE")

echo "Auditing foreground tokens against background: $BG"
echo "Standard: WCAG AA (4.5:1 for body text)"
echo ""

# Get foreground tokens and check each one
jq -r '.foreground | to_entries[] | "\(.key) \(.value)"' "$TOKENS_FILE" | while read -r token_name token_color; do
  # Use klar to check contrast ratio against WCAG2
  result=$(klar contrast "$token_color" "$BG" --type wcag2 --json 2>/dev/null || echo '{"contrast": null}')
  wcag_ratio=$(echo "$result" | jq -r '.contrast')

  # Determine pass/fail for WCAG AA (4.5:1) using awk for floating-point comparison
  status=$(awk -v ratio="$wcag_ratio" 'BEGIN {
    if (ratio == "null" || ratio == "") {
      print "ERROR"
    } else if (ratio >= 4.5) {
      print "PASS"
    } else {
      print "FAIL"
    }
  }')

  printf "%-15s %-40s %6.2f:1 %s\n" "$token_name" "$token_color" "$wcag_ratio" "$status"
done

